const VERSION="kamakura-540-25-v1";
const UNIT_ID="sapix-540-25";
const QUESTION_REVISIONS={"54025-01":[{"revision":1,"kind":"initial","reason":"PR #18 baseline","question":{"id":"54025-01","unitId":"sapix-540-25","course":"d1","level":1,"unit":"平氏","source":"教材準拠","type":"text","prompt":"1167年、武士として初めて太政大臣になった人物は？","answer":"平清盛","hint":"平氏の中心人物。厳島神社を保護したよ。","explanation":"平清盛は保元の乱・平治の乱に勝って力をのばし、1167年に武士として初めて太政大臣になりました。娘を天皇の后にし、生まれた子を天皇にしました。","pitfall":"太政大臣は朝廷の最高の地位。「武士なのに貴族のような政治をした」ことが反感を買ったよ。","pair":"","aliases":[],"readings":["たいらのきよもり"]}}],"54025-02":[{"revision":1,"kind":"initial","reason":"PR #18 baseline","question":{"id":"54025-02","unitId":"sapix-540-25","course":"d1","level":1,"unit":"平氏","source":"教材準拠","type":"choice","prompt":"1159年、都で源氏と平氏が戦い、平清盛が勝った戦いは？","answer":"平治の乱","hint":"保元の乱の3年後に起こったよ。","explanation":"平治の乱（1159年）で勝った平清盛は大きな力を持ち、やぶれた源氏の勢力は弱まりました。","pitfall":"保元の乱（1156年）→平治の乱（1159年）の順。「保」が先、「平」が後。どちらも清盛が勝った側。","pair":"ran","options":["平治の乱","保元の乱","承久の乱","応仁の乱"]}}],"54025-03":[{"revision":1,"kind":"initial","reason":"PR #18 baseline","question":{"id":"54025-03","unitId":"sapix-540-25","course":"d2","level":2,"unit":"平氏","source":"教材準拠","type":"choice","prompt":"1156年に都で起こり、平清盛らが勝った争いは？","answer":"保元の乱","hint":"平治の乱より3年前だよ。","explanation":"保元の乱（1156年）と平治の乱（1159年）に勝ったことで、平清盛は力を強めました。","pitfall":"保元の乱（1156年）→平治の乱（1159年）の順。承久の乱は鎌倉時代（1221年）。","pair":"ran","options":["保元の乱","平治の乱","承久の乱","壬申の乱"]}}],"54025-04":[{"revision":1,"kind":"initial","reason":"PR #18 baseline","question":{"id":"54025-04","unitId":"sapix-540-25","course":"d2","level":2,"unit":"平氏","source":"教材準拠","type":"text","prompt":"平清盛が中国（宋）と行った貿易は？","answer":"日宋貿易","hint":"当時の中国の王朝の名前が入るよ。","explanation":"平清盛は中国の宋との日宋貿易で大きな利益をあげました。そのために大輪田泊（今の神戸港）を改修しました。","pitfall":"平安末＝日宋貿易（宋）。室町時代の足利義満は日明貿易（明）。王朝名で区別しよう。","pair":"","aliases":[],"readings":["にっそうぼうえき"]}}],"54025-05":[{"revision":1,"kind":"initial","reason":"PR #18 baseline","question":{"id":"54025-05","unitId":"sapix-540-25","course":"d2","level":2,"unit":"平氏","source":"教材準拠","type":"text","prompt":"日宋貿易のために平清盛が改修した港（今の神戸港）は？","answer":"大輪田泊","hint":"「〇〇〇のとまり」と読むよ。","explanation":"平清盛は大輪田泊（今の兵庫県神戸市）を改修して、宋の船が来られるようにしました。","pitfall":"「泊」は船がとまる港のこと。大輪田泊＝今の神戸港。","pair":"","aliases":[],"readings":["おおわだのとまり"]}}],"54025-06":[{"revision":1,"kind":"initial","reason":"PR #18 baseline","question":{"id":"54025-06","unitId":"sapix-540-25","course":"d1","level":1,"unit":"平氏","source":"教材準拠","type":"choice","prompt":"平清盛が瀬戸内海の航路の安全を願って保護した神社は？","answer":"厳島神社","hint":"広島県の、海の中に鳥居が立つ神社だよ。","explanation":"平清盛は瀬戸内海の航路の安全を願い、厳島神社（広島県）を保護しました。","pitfall":"厳島神社＝平氏（清盛）、鶴岡八幡宮＝源氏の守り神（鎌倉）。","pair":"","options":["厳島神社","鶴岡八幡宮","出雲大社","伊勢神宮"]}}],"54025-07":[{"revision":1,"kind":"initial","reason":"PR #18 baseline","question":{"id":"54025-07","unitId":"sapix-540-25","course":"d1","level":1,"unit":"源平の争乱","source":"教材準拠","type":"text","prompt":"1180年に伊豆で兵を挙げ、のちに鎌倉幕府を開いた人物は？","answer":"源頼朝","hint":"13歳で伊豆に流され、そこで北条氏と出会ったよ。","explanation":"源頼朝は1180年に伊豆で兵を挙げ、北条氏などの関東の武士を味方につけました。平氏をたおした後、鎌倉に幕府を開きました。","pitfall":"頼朝＝兵を挙げて幕府を開いた兄、義経＝平氏と戦った弟。","pair":"genji","aliases":[],"readings":["みなもとのよりとも"]}}],"54025-08":[{"revision":1,"kind":"initial","reason":"PR #18 baseline","question":{"id":"54025-08","unitId":"sapix-540-25","course":"d1","level":1,"unit":"源平の争乱","source":"教材準拠","type":"text","prompt":"1185年、平氏が滅亡した戦いは？","answer":"壇ノ浦の戦い","hint":"本州の西のはし（山口県）の海での戦いだよ。","explanation":"1185年、源義経の軍に追いつめられた平氏は、壇ノ浦（山口県）の戦いで滅亡しました。幼い安徳天皇もこのとき亡くなりました。","pitfall":"一ノ谷（1184年）→屋島（1185年）→壇ノ浦（1185年）の順に西へ。最後が壇ノ浦。","pair":"","aliases":["壇の浦の戦い","壇ノ浦の合戦","壇の浦の合戦"],"readings":["だんのうらのたたかい"]}}],"54025-09":[{"revision":1,"kind":"initial","reason":"PR #18 baseline","question":{"id":"54025-09","unitId":"sapix-540-25","course":"d2","level":2,"unit":"源平の争乱","source":"教材準拠","type":"choice","prompt":"一ノ谷・屋島・壇ノ浦の戦いで平氏をやぶった、頼朝の弟は？","answer":"源義経","hint":"子どものころは「牛若丸」とよばれていたよ。","explanation":"源義経は頼朝の弟で、平氏を次々にやぶりました。のちに兄の頼朝と対立し、平泉（奥州藤原氏のもと）で倒されました。","pitfall":"義経＝一ノ谷・屋島・壇ノ浦、義仲＝倶利伽羅峠。どちらも「源義〇」なので注意。","pair":"genji","options":["源義経","源義仲","源頼家","北条義時"]}}],"54025-10":[{"revision":1,"kind":"initial","reason":"PR #18 baseline","question":{"id":"54025-10","unitId":"sapix-540-25","course":"d2","level":2,"unit":"源平の争乱","source":"教材準拠","type":"choice","prompt":"倶利伽羅峠の戦いで、牛の角にたいまつをつけて平氏をやぶったと伝えられる人物は？","answer":"源義仲","hint":"木曽（長野県）で兵を挙げた人物で、「木曽義仲」ともよばれるよ。","explanation":"源義仲は1183年の倶利伽羅峠の戦いで平氏をやぶり京都に入りましたが、のちに頼朝が送った軍に倒されました。","pitfall":"義仲＝倶利伽羅峠（1183年）、義経＝一ノ谷・屋島・壇ノ浦。","pair":"genji","options":["源義仲","源義経","源頼朝","平清盛"]}}],"54025-11":[{"revision":1,"kind":"initial","reason":"PR #18 baseline","question":{"id":"54025-11","unitId":"sapix-540-25","course":"d3","level":3,"unit":"源平の争乱","source":"教材準拠","type":"choice","prompt":"屋島の戦いで、平氏の船の上にかかげられた扇を射抜いたと伝えられる人物は？","answer":"那須与一","hint":"弓の名手として知られる人物だよ。","explanation":"屋島の戦い（1185年、香川県）では、源氏の弓の名手・那須与一が、遠くの船の上の扇を見事に射抜いたと伝えられています。","pitfall":"屋島＝那須与一の扇の的。伝説として語られている話だよ。","pair":"","options":["那須与一","源義経","武蔵坊弁慶","北条時政"]}}],"54025-12":[{"revision":1,"kind":"initial","reason":"PR #18 baseline","question":{"id":"54025-12","unitId":"sapix-540-25","course":"d1","level":1,"unit":"鎌倉幕府","source":"教材準拠","type":"text","prompt":"国ごとに置かれ、軍事や警察の仕事をした役職は？","answer":"守護","hint":"「守る」という字が入るよ。","explanation":"源頼朝は国ごとに守護を置き、軍事や警察などの仕事をさせました。","pitfall":"守護＝国ごと・軍事と警察、地頭＝荘園ごと・土地の管理と年貢。「守る」のが守護。","pair":"shugo","aliases":[],"readings":["しゅご"]}}],"54025-13":[{"revision":1,"kind":"initial","reason":"PR #18 baseline","question":{"id":"54025-13","unitId":"sapix-540-25","course":"d1","level":1,"unit":"鎌倉幕府","source":"教材準拠","type":"text","prompt":"荘園ごとに置かれ、土地の管理や年貢の取り立てをした役職は？","answer":"地頭","hint":"「土地」の「地」の字が入るよ。","explanation":"地頭は主に荘園ごとに置かれ、土地の管理や農民からの年貢（税）の取り立てなどを行いました。","pitfall":"守護＝国ごと・軍事と警察、地頭＝荘園ごと・土地と年貢。「土地」なら地頭。","pair":"shugo","aliases":[],"readings":["じとう"]}}],"54025-14":[{"revision":1,"kind":"initial","reason":"PR #18 baseline","question":{"id":"54025-14","unitId":"sapix-540-25","course":"d2","level":2,"unit":"鎌倉幕府","source":"教材準拠","type":"text","prompt":"1192年、源頼朝が朝廷から任命された役職は？","answer":"征夷大将軍","hint":"「〇〇〇大将軍」という6文字の役職だよ。","explanation":"1192年、源頼朝は朝廷から征夷大将軍に任命されました。ここから始まる時代を鎌倉時代といいます（幕府の成立を1185年とする考え方もあります）。","pitfall":"1185年＝守護・地頭を置く、1192年＝征夷大将軍。どちらの年も問われるよ。","pair":"","aliases":[],"readings":["せいいたいしょうぐん"]}}],"54025-15":[{"revision":1,"kind":"initial","reason":"PR #18 baseline","question":{"id":"54025-15","unitId":"sapix-540-25","course":"d1","level":1,"unit":"鎌倉幕府","source":"教材準拠","type":"text","prompt":"将軍から領地を認めてもらう代わりに、将軍に忠誠をちかった武士を何という？","answer":"御家人","hint":"将軍の家来のことで、「御」の字から始まるよ。","explanation":"将軍の家来となった武士を御家人といいます。将軍と御家人は「御恩と奉公」の関係で結ばれていました。","pitfall":"御家人＝人、御恩＝将軍がすること、奉公＝御家人がすること。","pair":"","aliases":[],"readings":["ごけにん"]}}],"54025-16":[{"revision":1,"kind":"initial","reason":"PR #18 baseline","question":{"id":"54025-16","unitId":"sapix-540-25","course":"d2","level":2,"unit":"鎌倉幕府","source":"教材準拠","type":"choice","prompt":"将軍が、御家人の領地を認めたり新しい領地を与えたりすることを何という？","answer":"御恩","hint":"「恩」を与えるのは将軍の側だよ。","explanation":"将軍は御家人の領地を認めたり、手がらに応じて新しい領地を与えたり、守護や地頭に任命したりしました。これを御恩といいます。","pitfall":"将軍→御家人＝御恩、御家人→将軍＝奉公。土地を仲立ちにした関係を封建制度というよ。","pair":"goon","options":["御恩","奉公","年貢","徳政"]}}],"54025-17":[{"revision":1,"kind":"initial","reason":"PR #18 baseline","question":{"id":"54025-17","unitId":"sapix-540-25","course":"d2","level":2,"unit":"鎌倉幕府","source":"教材準拠","type":"choice","prompt":"御家人が、将軍のために命がけで戦ったり鎌倉や京都を守ったりすることを何という？","answer":"奉公","hint":"御家人が将軍に「仕える」ことだよ。","explanation":"御家人は御恩を受ける代わりに、いざというときは将軍のために命がけで戦い、ふだんは京都や鎌倉を守る役につきました。これを奉公といいます。","pitfall":"将軍→御家人＝御恩、御家人→将軍＝奉公。","pair":"goon","options":["奉公","御恩","一揆","寄合"]}}],"54025-18":[{"revision":1,"kind":"initial","reason":"PR #18 baseline","question":{"id":"54025-18","unitId":"sapix-540-25","course":"d2","level":2,"unit":"鎌倉幕府","source":"教材準拠","type":"choice","prompt":"鎌倉幕府で、裁判に関する仕事をした役所は？","answer":"問注所","hint":"「問う」という字が入っているよ。","explanation":"鎌倉には、御家人を取りしまる侍所、政治を行う政所、裁判を行う問注所が置かれました。","pitfall":"侍所＝侍（御家人）の取りしまり、政所＝政治、問注所＝問いただす（裁判）。字の意味で覚えよう。","pair":"office","options":["問注所","侍所","政所","六波羅探題"]}}],"54025-19":[{"revision":1,"kind":"initial","reason":"PR #18 baseline","question":{"id":"54025-19","unitId":"sapix-540-25","course":"d2","level":2,"unit":"鎌倉幕府","source":"教材準拠","type":"choice","prompt":"鎌倉幕府で、御家人の取りしまりをした役所は？","answer":"侍所","hint":"御家人は武士＝「さむらい」だよ。","explanation":"侍所は御家人の取りしまりをする役所です。政所は政治（はじめは公文所といいました）、問注所は裁判を担当しました。","pitfall":"侍所＝侍の取りしまり、政所＝政治、問注所＝裁判。","pair":"office","options":["侍所","政所","問注所","公文所"]}}],"54025-20":[{"revision":1,"kind":"initial","reason":"PR #18 baseline","question":{"id":"54025-20","unitId":"sapix-540-25","course":"d2","level":2,"unit":"鎌倉幕府","source":"教材準拠","type":"text","prompt":"鎌倉と各地を結ぶため、山や丘を切り開いてつくった道は？","answer":"切通し","hint":"山を「切って」「通した」道だよ。","explanation":"鎌倉は三方を山、一方を海に囲まれて守りやすい土地でした。人や馬が行き来できるように、山や丘を切り開いた切通しがつくられました。","pitfall":"鎌倉が守りやすい理由＝三方が山・一方が海。出入り口が切通し。","pair":"","aliases":["切り通し"],"readings":["きりどおし"]}}],"54025-21":[{"revision":1,"kind":"initial","reason":"PR #18 baseline","question":{"id":"54025-21","unitId":"sapix-540-25","course":"d1","level":1,"unit":"北条氏","source":"教材準拠","type":"text","prompt":"将軍を助ける役職で、北条氏が代々ついたものは？","answer":"執権","hint":"「権力を執る」と書くよ。","explanation":"鎌倉幕府では将軍を助ける執権が置かれ、北条氏が代々その地位につきました。執権の北条氏が将軍をおさえて幕府の政治を動かすようになりました。","pitfall":"室町幕府で将軍を補佐したのは管領。鎌倉＝執権、室町＝管領。","pair":"","aliases":[],"readings":["しっけん"]}}],"54025-22":[{"revision":1,"kind":"initial","reason":"PR #18 baseline","question":{"id":"54025-22","unitId":"sapix-540-25","course":"d2","level":2,"unit":"北条氏","source":"教材準拠","type":"text","prompt":"源頼朝の妻で、頼朝の死後「尼将軍」とよばれた人物は？","answer":"北条政子","hint":"初代執権北条時政の娘だよ。","explanation":"北条政子は頼朝の妻で、頼朝の死後は幕府の実力者として「尼将軍」とよばれました。承久の乱では御家人たちにうったえ、団結させました。","pitfall":"政子＝頼朝の妻・尼将軍、時政＝政子の父・初代執権。","pair":"hojo","aliases":[],"readings":["ほうじょうまさこ"]}}],"54025-23":[{"revision":1,"kind":"initial","reason":"PR #18 baseline","question":{"id":"54025-23","unitId":"sapix-540-25","course":"d2","level":2,"unit":"北条氏","source":"教材準拠","type":"text","prompt":"1221年、後鳥羽上皇が幕府をたおそうとして兵を挙げ、敗れた戦いは？","answer":"承久の乱","hint":"元号の名前がつく乱だよ。","explanation":"1221年、後鳥羽上皇は2代執権北条義時をたおすよう命じて兵を挙げましたが、北条政子のうったえで団結した御家人の軍に敗れました。","pitfall":"承久の乱＝1221年・後鳥羽上皇。平安末の保元の乱・平治の乱と取り違えないように。","pair":"","aliases":[],"readings":["じょうきゅうのらん"]}}],"54025-24":[{"revision":1,"kind":"initial","reason":"PR #18 baseline","question":{"id":"54025-24","unitId":"sapix-540-25","course":"d2","level":2,"unit":"北条氏","source":"教材準拠","type":"choice","prompt":"承久の乱の後、朝廷の監視や西国の武士の統制のため京都に置かれた役所は？","answer":"六波羅探題","hint":"京都の地名がついた役所だよ。","explanation":"承久の乱の後、幕府は後鳥羽上皇を隠岐（島根県）へ流し、京都に六波羅探題を置いて朝廷の監視や西国の武士の統制を行いました。","pitfall":"六波羅探題＝承久の乱の後・京都。侍所・政所・問注所は鎌倉にある役所。","pair":"","options":["六波羅探題","問注所","政所","侍所"]}}],"54025-25":[{"revision":1,"kind":"initial","reason":"PR #18 baseline","question":{"id":"54025-25","unitId":"sapix-540-25","course":"d2","level":2,"unit":"北条氏","source":"教材準拠","type":"text","prompt":"1232年、3代執権北条泰時が定めた、武士がつくった最初の法律は？","answer":"御成敗式目","hint":"「貞永式目」ともいうよ。","explanation":"北条泰時は、土地をめぐる争いをさばく裁判の基準として御成敗式目（貞永式目）を定めました。武士がつくった最初の法律で、のちの武家法の手本になりました。","pitfall":"御成敗式目＝1232年・3代執権北条泰時。承久の乱の義時（2代）と区別しよう。","pair":"hojo","aliases":["貞永式目"],"readings":["ごせいばいしきもく","じょうえいしきもく"]}}],"54025-26":[{"revision":1,"kind":"initial","reason":"PR #18 baseline","question":{"id":"54025-26","unitId":"sapix-540-25","course":"d3","level":3,"unit":"北条氏","source":"教材準拠","type":"choice","prompt":"承久の乱のとき、後鳥羽上皇に討つよう命じられた2代執権は？","answer":"北条義時","hint":"政子の弟だよ。御成敗式目を定めた人物の父でもあるよ。","explanation":"後鳥羽上皇は2代執権北条義時をたおすよう命じましたが、幕府軍が勝ちました。","pitfall":"初代＝時政（政子の父）、2代＝義時（承久の乱）、3代＝泰時（御成敗式目）。","pair":"hojo","options":["北条義時","北条泰時","北条時政","北条政子"]}}],"54025-27":[{"revision":1,"kind":"initial","reason":"PR #18 baseline","question":{"id":"54025-27","unitId":"sapix-540-25","course":"d1","level":1,"unit":"武士のくらし","source":"教材準拠","type":"choice","prompt":"走る馬の上から、3つの的に向かって次々に矢を射る武芸は？","answer":"流鏑馬","hint":"今も神社の行事で見られることがあるよ。","explanation":"鎌倉時代の武士の戦いは馬に乗った一騎打ちが基本でした。そのため、流鏑馬・笠懸・犬追物などで、ふだんから馬に乗って弓を射る訓練をしました。","pitfall":"流鏑馬＝3つの的、笠懸＝遠くに置いた笠。蹴鞠は貴族の遊び。","pair":"","options":["流鏑馬","笠懸","犬追物","蹴鞠"]}}],"54025-28":[{"revision":1,"kind":"initial","reason":"PR #18 baseline","question":{"id":"54025-28","unitId":"sapix-540-25","course":"d2","level":2,"unit":"武士のくらし","source":"教材準拠","type":"text","prompt":"「一か所の領地を命がけで守る」ことから生まれ、今の「一生懸命」のもとになった言葉は？","answer":"一所懸命","hint":"「一生」ではなく「一〇」と書くよ。","explanation":"武士は自分の領地を命がけで守り、それを生活のよりどころにしていました。そこから「一所懸命」という言葉が生まれました。","pitfall":"一所＝一か所の領地。「一生懸命」と書かないように。","pair":"","aliases":[],"readings":["いっしょけんめい"]}}],"54025-29":[{"revision":1,"kind":"initial","reason":"PR #18 baseline","question":{"id":"54025-29","unitId":"sapix-540-25","course":"d2","level":2,"unit":"武士のくらし","source":"教材準拠","type":"choice","prompt":"幕府に大事が起きたとき、御家人がすぐに鎌倉へかけつける心意気を表す言葉は？","answer":"いざ鎌倉","hint":"「もしもの時は急いで鎌倉へ」という意味だよ。","explanation":"御家人はふだんは自分の領地でくらし、幕府に大事が起きると鎌倉へかけつけました。「いざ鎌倉」はこの心意気が由来です。各地と鎌倉は鎌倉街道で結ばれていました。","pitfall":"いざ鎌倉＝鎌倉へかけつける、一所懸命＝領地を守る。","pair":"","options":["いざ鎌倉","一所懸命","下剋上","御恩と奉公"]}}],"54025-30":[{"revision":1,"kind":"initial","reason":"PR #18 baseline","question":{"id":"54025-30","unitId":"sapix-540-25","course":"d1","level":1,"unit":"新しい仏教","source":"教材準拠","type":"text","prompt":"「南無阿弥陀仏」と念仏を唱えればだれでも極楽浄土へ行けると説き、浄土宗を開いたのは？","answer":"法然","hint":"親鸞の師だよ。","explanation":"法然は、念仏を唱えればだれでも救われると説いて浄土宗を開き、貴族・武士・庶民に広まりました。","pitfall":"法然（師）＝浄土宗、親鸞（弟子）＝浄土真宗。「真」がつく方が弟子。","pair":"jodo","aliases":[],"readings":["ほうねん"]}}],"54025-31":[{"revision":1,"kind":"initial","reason":"PR #18 baseline","question":{"id":"54025-31","unitId":"sapix-540-25","course":"d2","level":2,"unit":"新しい仏教","source":"教材準拠","type":"text","prompt":"法然の弟子で、阿弥陀仏を信じれば救われると説き、浄土真宗（一向宗）を開いたのは？","answer":"親鸞","hint":"関東の武士や庶民に教えが広まったよ。","explanation":"親鸞は法然の教えをさらにおし進め、阿弥陀仏を信じさえすれば救われると説いて浄土真宗（一向宗）を開きました。","pitfall":"法然（師）＝浄土宗、親鸞（弟子）＝浄土真宗。一向宗は室町時代の一向一揆にもつながるよ。","pair":"jodo","aliases":[],"readings":["しんらん"]}}],"54025-32":[{"revision":1,"kind":"initial","reason":"PR #18 baseline","question":{"id":"54025-32","unitId":"sapix-540-25","course":"d2","level":2,"unit":"新しい仏教","source":"教材準拠","type":"choice","prompt":"各地をまわって踊念仏を広め、時宗を開いたのは？","answer":"一遍","hint":"踊りながら念仏を唱えたよ。","explanation":"一遍は、踊りながら念仏を唱える踊念仏で教えを広め、時宗を開きました。","pitfall":"念仏の宗派：浄土宗（法然）・浄土真宗（親鸞）・時宗（一遍）。","pair":"","options":["一遍","日蓮","法然","道元"]}}],"54025-33":[{"revision":1,"kind":"initial","reason":"PR #18 baseline","question":{"id":"54025-33","unitId":"sapix-540-25","course":"d2","level":2,"unit":"新しい仏教","source":"教材準拠","type":"text","prompt":"「南無妙法蓮華経」と題目を唱えれば人も国も救われると説き、日蓮宗を開いたのは？","answer":"日蓮","hint":"宗派の名前と同じ名前の人物だよ。","explanation":"日蓮は法華経を信じ、「南無妙法蓮華経」という題目を唱えれば人も国も救われると説いて日蓮宗（法華宗）を開きました。他の宗派をきびしく批判しました。","pitfall":"念仏＝南無阿弥陀仏（法然・親鸞・一遍）、題目＝南無妙法蓮華経（日蓮）。","pair":"","aliases":[],"readings":["にちれん"]}}],"54025-34":[{"revision":1,"kind":"initial","reason":"PR #18 baseline","question":{"id":"54025-34","unitId":"sapix-540-25","course":"d2","level":2,"unit":"新しい仏教","source":"教材準拠","type":"choice","prompt":"宋で修行し、座禅を重視する臨済宗を開いたのは？","answer":"栄西","hint":"幕府の上級武士などに広まった禅宗だよ。","explanation":"栄西は宋で修行して帰国後に臨済宗を開きました。臨済宗は貴族や将軍家、幕府の上級武士に広まりました。","pitfall":"栄西＝臨済宗（幕府の上級武士）、道元＝曹洞宗（地方の武士）。どちらも座禅の禅宗。","pair":"zen","options":["栄西","道元","親鸞","一遍"]}}],"54025-35":[{"revision":1,"kind":"initial","reason":"PR #18 baseline","question":{"id":"54025-35","unitId":"sapix-540-25","course":"d2","level":2,"unit":"新しい仏教","source":"教材準拠","type":"choice","prompt":"宋で修行し、座禅を重視する曹洞宗を開いたのは？","answer":"道元","hint":"地方の武士に広まった禅宗だよ。","explanation":"道元も宋で修行し、ひたすら座禅を行うことを重視して曹洞宗を開きました。曹洞宗は地方の武士に広まりました。","pitfall":"栄西＝臨済宗、道元＝曹洞宗。「栄・臨」「道・曹」とセットで覚えよう。","pair":"zen","options":["道元","栄西","日蓮","法然"]}}],"54025-36":[{"revision":1,"kind":"initial","reason":"PR #18 baseline","question":{"id":"54025-36","unitId":"sapix-540-25","course":"d1","level":1,"unit":"鎌倉文化","source":"教材準拠","type":"choice","prompt":"東大寺南大門の金剛力士像をつくった人物の組み合わせは？","answer":"運慶と快慶","hint":"どちらも名前に「慶」の字がつくよ。","explanation":"東大寺南大門は鎌倉時代を代表する建築物で、その内部には運慶・快慶らがつくった2体の金剛力士像が納められています。","pitfall":"鎌倉文化＝質素で力強い。東大寺南大門・金剛力士像（運慶・快慶）。","pair":"","options":["運慶と快慶","法然と親鸞","栄西と道元","平清盛と源頼朝"]}}],"54025-37":[{"revision":1,"kind":"initial","reason":"PR #18 baseline","question":{"id":"54025-37","unitId":"sapix-540-25","course":"d2","level":2,"unit":"鎌倉文化","source":"教材準拠","type":"text","prompt":"琵琶法師が語り伝えた、平氏の繁栄から滅亡までをえがいた物語は？","answer":"平家物語","hint":"平氏のことを「平家」ともいうよ。","explanation":"『平家物語』は平氏の繁栄から滅亡までをえがいた物語で、琵琶法師によって各地に語り伝えられました。","pitfall":"平家物語＝琵琶法師が語る。平安時代の『源氏物語』（紫式部）と取り違えないように。","pair":"","aliases":[],"readings":["へいけものがたり"]}}],"54025-38":[{"revision":1,"kind":"initial","reason":"PR #18 baseline","question":{"id":"54025-38","unitId":"sapix-540-25","course":"d3","level":3,"unit":"新しい仏教","source":"教材準拠","type":"choice","prompt":"鎌倉時代に新しい仏教が人々の間に広まった理由として、最もふさわしいものは？","answer":"念仏や題目を唱えるなど、教えがわかりやすかったから","hint":"戦乱や災害が続き、不安になった人々は何を求めたかな？","explanation":"平安時代の終わりから戦乱や災害が続き、人々は仏教に救いを求めました。新しい仏教は伝統的な仏教に比べて教えがわかりやすく、だれでも救われると説いたため広まりました。","pitfall":"「戦乱・災害で不安」→「わかりやすい教え」→「庶民にも広まる」の順につなげよう。","pair":"","options":["念仏や題目を唱えるなど、教えがわかりやすかったから","寺に多くのお金を納めた人だけが救われる教えだったから","貴族だけが学べるむずかしい教えだったから","中国の皇帝が日本に広めるよう命じたから"]}}]};
