const normalize=s=>s.normalize('NFKC').trim().replace(/[\s・、／/『』「」]/g,'').replace(/[ァ-ヶ]/g,c=>String.fromCharCode(c.charCodeAt(0)-0x60));
const VERSION="heian-540-24-v1";
const QUESTION_REVISIONS={"h24-m01":[{"revision":1,"kind":"initial","reason":"PR #18 baseline","question":{"id":"h24-m01","course":"memory","unit":"藤原氏と政治","type":"text","prompt":"794年に移された都は？","answer":"平安京","aliases":[],"readings":["へいあんきょう"],"hint":"人物・役職・年号のどれが聞かれているか見てみよう。","explanation":"794年、桓武天皇が平安京に都を移しました。今の京都市にあたります。","priority":1}}],"h24-m02":[{"revision":1,"kind":"initial","reason":"PR #18 baseline","question":{"id":"h24-m02","course":"memory","unit":"藤原氏と政治","type":"text","prompt":"摂政・関白を独占した一族は？","answer":"藤原氏","aliases":[],"readings":["ふじわらし"],"hint":"人物・役職・年号のどれが聞かれているか見てみよう。","explanation":"藤原氏は天皇の母方の親戚となり、摂政・関白を一族で占めて力を強めました。","priority":1}}],"h24-m03":[{"revision":1,"kind":"initial","reason":"PR #18 baseline","question":{"id":"h24-m03","course":"memory","unit":"藤原氏と政治","type":"text","prompt":"藤原氏の祖先とされる鎌足の名前は？","answer":"中臣鎌足","aliases":["藤原鎌足"],"readings":["なかとみのかまたり","ふじわらのかまたり"],"hint":"人物・役職・年号のどれが聞かれているか見てみよう。","explanation":"中臣鎌足は藤原の姓を与えられました。藤原鎌足とも呼びます。","priority":1}}],"h24-m04":[{"revision":1,"kind":"initial","reason":"PR #18 baseline","question":{"id":"h24-m04","course":"memory","unit":"藤原氏と政治","type":"text","prompt":"幼い天皇などに代わって政治を行う役職は？","answer":"摂政","aliases":[],"readings":["せっしょう"],"hint":"人物・役職・年号のどれが聞かれているか見てみよう。","explanation":"摂政は、幼い天皇などに代わって政治を行う役職です。女性天皇なら必ず摂政が置かれる、という決まりではありません。","priority":2}}],"h24-m05":[{"revision":1,"kind":"initial","reason":"PR #18 baseline","question":{"id":"h24-m05","course":"memory","unit":"藤原氏と政治","type":"text","prompt":"成人した天皇を補佐する役職は？","answer":"関白","aliases":[],"readings":["かんぱく"],"hint":"人物・役職・年号のどれが聞かれているか見てみよう。","explanation":"関白は成人した天皇を補佐する役職です。摂政との違いは天皇の年齢と役割で整理しましょう。","priority":2}}],"h24-m06":[{"revision":1,"kind":"initial","reason":"PR #18 baseline","question":{"id":"h24-m06","course":"memory","unit":"藤原氏と政治","type":"text","prompt":"摂政・関白が中心となって行う政治を何という？","answer":"摂関政治","aliases":[],"readings":["せっかんせいじ"],"hint":"人物・役職・年号のどれが聞かれているか見てみよう。","explanation":"藤原氏が摂政・関白として政治の実権を握った政治を、摂関政治といいます。","priority":1}}],"h24-m07":[{"revision":1,"kind":"initial","reason":"PR #18 baseline","question":{"id":"h24-m07","course":"memory","unit":"藤原氏と政治","type":"text","prompt":"母方の親戚のことを何という？","answer":"外戚","aliases":[],"readings":["がいせき"],"hint":"人物・役職・年号のどれが聞かれているか見てみよう。","explanation":"外戚は母方の親戚。藤原氏は娘を天皇の后にし、孫が天皇になることで外戚となりました。","priority":1}}],"h24-m08":[{"revision":1,"kind":"initial","reason":"PR #18 baseline","question":{"id":"h24-m08","course":"memory","unit":"藤原氏と政治","type":"text","prompt":"摂関政治の全盛期の父と子を、父→子の順に「・」で区切って答えよう。","answer":"藤原道長・藤原頼通","aliases":[],"readings":["ふじわらのみちなが・ふじわらのよりみち"],"hint":"人物・役職・年号のどれが聞かれているか見てみよう。","explanation":"道長と、その子の頼通のころ、藤原氏の摂関政治が全盛期を迎えました。","priority":1}}],"h24-m09":[{"revision":1,"kind":"initial","reason":"PR #18 baseline","question":{"id":"h24-m09","course":"memory","unit":"藤原氏と政治","type":"text","prompt":"1016年に摂政になった人物は？","answer":"藤原道長","aliases":[],"readings":["ふじわらのみちなが"],"hint":"人物・役職・年号のどれが聞かれているか見てみよう。","explanation":"1016年に摂政となったのは道長。平等院鳳凰堂を建てた頼通と区別しましょう。","priority":2}}],"h24-m10":[{"revision":1,"kind":"initial","reason":"PR #18 baseline","question":{"id":"h24-m10","course":"memory","unit":"藤原氏と政治","type":"text","prompt":"「この世をば　わが世とぞ思う…」をよんだのは？","answer":"藤原道長","aliases":[],"readings":["ふじわらのみちなが"],"hint":"人物・役職・年号のどれが聞かれているか見てみよう。","explanation":"望月は満月のこと。道長は欠けるところのない満月に自分の栄華を重ねました。","priority":1}}],"h24-m11":[{"revision":1,"kind":"initial","reason":"PR #18 baseline","question":{"id":"h24-m11","course":"memory","unit":"藤原氏と政治","type":"text","prompt":"道長が望月の歌を詠んだ日に后になった、三女の名前は？","answer":"威子","aliases":[],"readings":["いし","たけこ"],"hint":"人物・役職・年号のどれが聞かれているか見てみよう。","explanation":"道長の三女・威子が后になったときの歌です。威子の読みは「いし／たけこ」とされます。","priority":1}}],"h24-m12":[{"revision":1,"kind":"initial","reason":"PR #18 baseline","question":{"id":"h24-m12","course":"memory","unit":"藤原氏と政治","type":"text","prompt":"藤原氏が収入を得ていた私有地は？","answer":"荘園","aliases":[],"readings":["しょうえん"],"hint":"人物・役職・年号のどれが聞かれているか見てみよう。","explanation":"荘園は貴族や寺社などの私有地です。藤原氏は荘園から多くの収入を得ました。","priority":1}}],"h24-m13":[{"revision":1,"kind":"initial","reason":"PR #18 baseline","question":{"id":"h24-m13","course":"memory","unit":"藤原氏と政治","type":"text","prompt":"藤原氏のたくらみで大宰府へ追われた人物は？","answer":"菅原道真","aliases":[],"readings":["すがわらのみちざね"],"hint":"人物・役職・年号のどれが聞かれているか見てみよう。","explanation":"菅原道真は藤原時平との対立などを背景に、大宰府へ左遷されました。","priority":1}}],"h24-m14":[{"revision":1,"kind":"initial","reason":"PR #18 baseline","question":{"id":"h24-m14","course":"memory","unit":"藤原氏と政治","type":"text","prompt":"遣唐使の停止を提案した人物は？","answer":"菅原道真","aliases":[],"readings":["すがわらのみちざね"],"hint":"人物・役職・年号のどれが聞かれているか見てみよう。","explanation":"894年、菅原道真が遣唐使の派遣中止を提案しました。","priority":2}}],"h24-m15":[{"revision":1,"kind":"initial","reason":"PR #18 baseline","question":{"id":"h24-m15","course":"memory","unit":"藤原氏と政治","type":"text","prompt":"遣唐使が停止された年は？","answer":"894年","aliases":["894年"],"readings":["894"],"hint":"人物・役職・年号のどれが聞かれているか見てみよう。","explanation":"894年の遣唐使停止と794年の平安京遷都は100年違います。","priority":2}}],"h24-m16":[{"revision":1,"kind":"initial","reason":"PR #18 baseline","question":{"id":"h24-m16","course":"memory","unit":"藤原氏と政治","type":"text","prompt":"遣唐使停止の理由ではないのは「唐のおとろえ」「航海の危険」「唐と新羅の戦争」のどれ？","answer":"唐と新羅の戦争","aliases":[],"readings":["とうとしらぎのせんそう"],"hint":"人物・役職・年号のどれが聞かれているか見てみよう。","explanation":"遣唐使停止の背景は唐のおとろえや航海の危険など。「唐と新羅の戦争」はこの時の理由にあたりません。","priority":1}}],"h24-m17":[{"revision":1,"kind":"initial","reason":"PR #18 baseline","question":{"id":"h24-m17","course":"memory","unit":"国風文化とくらし","type":"text","prompt":"平安時代に栄えた日本独自の文化は？","answer":"国風文化","aliases":[],"readings":["こくふうぶんか"],"hint":"作品と作者、建物と建てた人を区別してみよう。","explanation":"中国から学んだ文化を、日本の風土や暮らしに合う形に発展させた国風文化が栄えました。","priority":1}}],"h24-m18":[{"revision":1,"kind":"initial","reason":"PR #18 baseline","question":{"id":"h24-m18","course":"memory","unit":"国風文化とくらし","type":"text","prompt":"漢字をくずしてつくった文字は？","answer":"ひらがな","aliases":[],"readings":["ひらがな"],"hint":"作品と作者、建物と建てた人を区別してみよう。","explanation":"ひらがなは漢字をくずしたもの。「安」から「あ」などの例があります。","priority":1}}],"h24-m19":[{"revision":1,"kind":"initial","reason":"PR #18 baseline","question":{"id":"h24-m19","course":"memory","unit":"国風文化とくらし","type":"text","prompt":"漢字の一部をとってつくった文字は？","answer":"カタカナ","aliases":[],"readings":["かたかな"],"hint":"作品と作者、建物と建てた人を区別してみよう。","explanation":"カタカナは漢字の一部を使ったもの。「阿」から「ア」などの例があります。","priority":1}}],"h24-m20":[{"revision":1,"kind":"initial","reason":"PR #18 baseline","question":{"id":"h24-m20","course":"memory","unit":"国風文化とくらし","type":"text","prompt":"『源氏物語』の作者は？","answer":"紫式部","aliases":[],"readings":["むらさきしきぶ"],"hint":"作品と作者、建物と建てた人を区別してみよう。","explanation":"紫式部は『源氏物語』。清少納言の『枕草子』とセットで区別しましょう。","priority":2}}],"h24-m21":[{"revision":1,"kind":"initial","reason":"PR #18 baseline","question":{"id":"h24-m21","course":"memory","unit":"国風文化とくらし","type":"text","prompt":"『枕草子』の作者は？","answer":"清少納言","aliases":[],"readings":["せいしょうなごん"],"hint":"作品と作者、建物と建てた人を区別してみよう。","explanation":"清少納言の『枕草子』は随筆です。紫式部の『源氏物語』は長編物語です。","priority":2}}],"h24-m22":[{"revision":1,"kind":"initial","reason":"PR #18 baseline","question":{"id":"h24-m22","course":"memory","unit":"国風文化とくらし","type":"text","prompt":"紫式部が書いた平安時代の長編物語は？","answer":"源氏物語","aliases":[],"readings":["げんじものがたり"],"hint":"作品と作者、建物と建てた人を区別してみよう。","explanation":"紫式部が書いた長編物語が『源氏物語』です。「世界最古」と断定する問題にはしていません。","priority":1}}],"h24-m23":[{"revision":1,"kind":"initial","reason":"PR #18 baseline","question":{"id":"h24-m23","course":"memory","unit":"国風文化とくらし","type":"text","prompt":"天皇の命令による初めての歌集は？","answer":"古今和歌集","aliases":[],"readings":["こきんわかしゅう"],"hint":"作品と作者、建物と建てた人を区別してみよう。","explanation":"『古今和歌集』は最初の勅撰和歌集。勅撰とは天皇の命令で編集されたことです。","priority":1}}],"h24-m24":[{"revision":1,"kind":"initial","reason":"PR #18 baseline","question":{"id":"h24-m24","course":"memory","unit":"国風文化とくらし","type":"text","prompt":"『古今和歌集』をまとめた中心人物は？","answer":"紀貫之","aliases":[],"readings":["きのつらゆき"],"hint":"作品と作者、建物と建てた人を区別してみよう。","explanation":"紀貫之らが編集しました。紀貫之一人だけで作ったわけではありません。","priority":1}}],"h24-m25":[{"revision":1,"kind":"initial","reason":"PR #18 baseline","question":{"id":"h24-m25","course":"memory","unit":"国風文化とくらし","type":"text","prompt":"紫式部が仕えた、道長の娘である后は？","answer":"彰子","aliases":["藤原彰子"],"readings":["しょうし","あきこ","ふじわらのしょうし"],"hint":"作品と作者、建物と建てた人を区別してみよう。","explanation":"紫式部は道長の娘・彰子に仕えました。清少納言は道隆の娘・定子です。","priority":1}}],"h24-m26":[{"revision":1,"kind":"initial","reason":"PR #18 baseline","question":{"id":"h24-m26","course":"memory","unit":"国風文化とくらし","type":"text","prompt":"清少納言が仕えた、道隆の娘である后は？","answer":"定子","aliases":["藤原定子"],"readings":["ていし","さだこ","ふじわらのていし"],"hint":"作品と作者、建物と建てた人を区別してみよう。","explanation":"清少納言は定子に仕えました。「定子・清少納言」「彰子・紫式部」を対応させましょう。","priority":1}}],"h24-m27":[{"revision":1,"kind":"initial","reason":"PR #18 baseline","question":{"id":"h24-m27","course":"memory","unit":"国風文化とくらし","type":"text","prompt":"藤原道長の日記で「世界の記憶」に登録されたものは？","answer":"御堂関白記","aliases":[],"readings":["みどうかんぱくき"],"hint":"作品と作者、建物と建てた人を区別してみよう。","explanation":"藤原道長の日記は『御堂関白記』。道長は関白にはなっていませんが、日記にはこの名がついています。","priority":1}}],"h24-m28":[{"revision":1,"kind":"initial","reason":"PR #18 baseline","question":{"id":"h24-m28","course":"memory","unit":"国風文化とくらし","type":"text","prompt":"貴族の屋敷の建築様式は？","answer":"寝殿造","aliases":["寝殿造り"],"readings":["しんでんづくり"],"hint":"作品と作者、建物と建てた人を区別してみよう。","explanation":"寝殿造は中央の寝殿と南の庭・池などが特徴です。鳳凰堂は貴族の住宅ではなく阿弥陀堂です。","priority":1}}],"h24-m29":[{"revision":1,"kind":"initial","reason":"PR #18 baseline","question":{"id":"h24-m29","course":"memory","unit":"国風文化とくらし","type":"text","prompt":"貴族の男性・女性の正式な服装を、男性→女性の順に「・」で区切って答えよう。","answer":"束帯・十二単","aliases":[],"readings":["そくたい・じゅうにひとえ"],"hint":"作品と作者、建物と建てた人を区別してみよう。","explanation":"男性の正式な服装が束帯、女性の正式な服装が十二単です。順番も確認しましょう。","priority":1}}],"h24-m30":[{"revision":1,"kind":"initial","reason":"PR #18 baseline","question":{"id":"h24-m30","course":"memory","unit":"国風文化とくらし","type":"text","prompt":"『源氏物語絵巻』のような日本風の絵を何という？","answer":"大和絵","aliases":[],"readings":["やまとえ"],"hint":"作品と作者、建物と建てた人を区別してみよう。","explanation":"大和絵は日本の風景や暮らしなどを描いた絵です。絵巻から当時の様子も読み取れます。","priority":1}}],"h24-m31":[{"revision":1,"kind":"initial","reason":"PR #18 baseline","question":{"id":"h24-m31","course":"memory","unit":"国風文化とくらし","type":"text","prompt":"盃が流れてくるまでに歌をよむ年中行事は？","answer":"曲水の宴","aliases":[],"readings":["きょくすいのえん"],"hint":"作品と作者、建物と建てた人を区別してみよう。","explanation":"曲水の宴は、曲がった水の流れに盃を流し、和歌を詠む行事です。","priority":1}}],"h24-m32":[{"revision":1,"kind":"initial","reason":"PR #18 baseline","question":{"id":"h24-m32","course":"memory","unit":"国風文化とくらし","type":"text","prompt":"藤原頼通が京都府宇治市に建てた阿弥陀堂の名前は？（建物名を最後まで）","answer":"平等院鳳凰堂","aliases":[],"readings":["びょうどういんほうおうどう"],"hint":"作品と作者、建物と建てた人を区別してみよう。","explanation":"平等院鳳凰堂は京都府宇治市にあります。寺院の阿弥陀堂です。","priority":1}}],"h24-m33":[{"revision":1,"kind":"initial","reason":"PR #18 baseline","question":{"id":"h24-m33","course":"memory","unit":"国風文化とくらし","type":"text","prompt":"平等院鳳凰堂を建てた人物は？","answer":"藤原頼通","aliases":[],"readings":["ふじわらのよりみち"],"hint":"作品と作者、建物と建てた人を区別してみよう。","explanation":"1053年、藤原頼通が建てました。父の道長と取り違えないようにしましょう。","priority":2}}],"h24-m34":[{"revision":1,"kind":"initial","reason":"PR #18 baseline","question":{"id":"h24-m34","course":"memory","unit":"国風文化とくらし","type":"text","prompt":"頼通が信じた教えは？","answer":"浄土教","aliases":[],"readings":["じょうどきょう"],"hint":"作品と作者、建物と建てた人を区別してみよう。","explanation":"浄土教は阿弥陀仏の極楽浄土への往生を願う教え。鳳凰堂にもその考えが表れています。","priority":1}}],"h24-m35":[{"revision":1,"kind":"initial","reason":"PR #18 baseline","question":{"id":"h24-m35","course":"memory","unit":"武士の誕生","type":"text","prompt":"朝廷から国ごとに派遣された役人は？","answer":"国司","aliases":[],"readings":["こくし"],"hint":"場所・人物・出来事をひと組にして考えよう。","explanation":"国司は朝廷から国ごとに派遣された役人です。政治を行う中心地は国府といいます。","priority":1}}],"h24-m36":[{"revision":1,"kind":"initial","reason":"PR #18 baseline","question":{"id":"h24-m36","course":"memory","unit":"武士の誕生","type":"text","prompt":"国司が政治を行った各国の中心地は？","answer":"国府","aliases":[],"readings":["こくふ"],"hint":"場所・人物・出来事をひと組にして考えよう。","explanation":"国司は人、国府は場所。この２つを区別しましょう。","priority":1}}],"h24-m37":[{"revision":1,"kind":"initial","reason":"PR #18 baseline","question":{"id":"h24-m37","course":"memory","unit":"武士の誕生","type":"text","prompt":"尾張国の農民たちにうったえられた国司は？","answer":"藤原元命","aliases":[],"readings":["ふじわらのもとなが"],"hint":"場所・人物・出来事をひと組にして考えよう。","explanation":"尾張国の郡司や農民たちは、国司・藤原元命の不正を朝廷に訴えました。","priority":1}}],"h24-m38":[{"revision":1,"kind":"initial","reason":"PR #18 baseline","question":{"id":"h24-m38","course":"memory","unit":"武士の誕生","type":"text","prompt":"源氏→平氏の順に、天皇の名に由来する２つの武士団名を「・」で区切って答えよう。","answer":"清和源氏・桓武平氏","aliases":[],"readings":["せいわげんじ・かんむへいし"],"hint":"場所・人物・出来事をひと組にして考えよう。","explanation":"清和源氏と桓武平氏は天皇の子孫を指導者に持つ有力な武士団でした。","priority":1}}],"h24-m39":[{"revision":1,"kind":"initial","reason":"PR #18 baseline","question":{"id":"h24-m39","course":"memory","unit":"武士の誕生","type":"text","prompt":"939年に関東地方で反乱を起こした人物は？","answer":"平将門","aliases":[],"readings":["たいらのまさかど"],"hint":"場所・人物・出来事をひと組にして考えよう。","explanation":"関東地方で反乱を起こしたのは平将門。「瀬戸内海・藤原純友」と対にして覚えましょう。","priority":2}}],"h24-m40":[{"revision":1,"kind":"initial","reason":"PR #18 baseline","question":{"id":"h24-m40","course":"memory","unit":"武士の誕生","type":"text","prompt":"「新皇」と名乗った人物は？","answer":"平将門","aliases":[],"readings":["たいらのまさかど"],"hint":"場所・人物・出来事をひと組にして考えよう。","explanation":"平将門は新皇と名乗りました。藤原純友ではありません。","priority":2}}],"h24-m41":[{"revision":1,"kind":"initial","reason":"PR #18 baseline","question":{"id":"h24-m41","course":"memory","unit":"武士の誕生","type":"text","prompt":"939年に瀬戸内海で反乱を起こした人物は？","answer":"藤原純友","aliases":[],"readings":["ふじわらのすみとも"],"hint":"場所・人物・出来事をひと組にして考えよう。","explanation":"藤原純友は瀬戸内海で海賊を率いて反乱を起こしました。関東の平将門と区別しましょう。","priority":2}}],"h24-m42":[{"revision":1,"kind":"initial","reason":"PR #18 baseline","question":{"id":"h24-m42","course":"memory","unit":"武士の誕生","type":"text","prompt":"藤原純友がのちにおそった九州の役所は？","answer":"大宰府","aliases":[],"readings":["だざいふ"],"hint":"場所・人物・出来事をひと組にして考えよう。","explanation":"藤原純友の勢力は九州の大宰府も襲いました。大宰府の「宰」の字に注意しましょう。","priority":1}}],"h24-m43":[{"revision":1,"kind":"initial","reason":"PR #18 baseline","question":{"id":"h24-m43","course":"memory","unit":"武士の誕生","type":"text","prompt":"1051年に東北地方で起きた戦乱は？","answer":"前九年合戦","aliases":["前九年の役"],"readings":["ぜんくねんかっせん","ぜんくねんのえき"],"hint":"場所・人物・出来事をひと組にして考えよう。","explanation":"前九年合戦は1051年に始まりました。後三年合戦は1083年です。","priority":1}}],"h24-m44":[{"revision":1,"kind":"initial","reason":"PR #18 baseline","question":{"id":"h24-m44","course":"memory","unit":"武士の誕生","type":"text","prompt":"1083年に東北地方で起きた戦乱は？","answer":"後三年合戦","aliases":["後三年の役"],"readings":["ごさんねんかっせん","ごさんねんのえき"],"hint":"場所・人物・出来事をひと組にして考えよう。","explanation":"後三年合戦は1083年に始まりました。先に起きたのは前九年合戦です。","priority":1}}],"h24-m45":[{"revision":1,"kind":"initial","reason":"PR #18 baseline","question":{"id":"h24-m45","course":"memory","unit":"武士の誕生","type":"text","prompt":"東北の戦乱をしずめ、東日本で力をのばした一族は？","answer":"源氏","aliases":[],"readings":["げんじ"],"hint":"場所・人物・出来事をひと組にして考えよう。","explanation":"源氏は東北での戦乱などを通して東日本の武士との結びつきを強めました。","priority":1}}],"h24-m46":[{"revision":1,"kind":"initial","reason":"PR #18 baseline","question":{"id":"h24-m46","course":"memory","unit":"武士の誕生","type":"text","prompt":"瀬戸内海を中心に西日本で力をのばした一族は？","answer":"平氏","aliases":[],"readings":["へいし"],"hint":"場所・人物・出来事をひと組にして考えよう。","explanation":"平氏は西日本、特に瀬戸内海を中心に力を伸ばしました。","priority":1}}],"h24-m47":[{"revision":1,"kind":"initial","reason":"PR #18 baseline","question":{"id":"h24-m47","course":"memory","unit":"武士の誕生","type":"text","prompt":"延暦寺などが持っていた武装した僧を何という？","answer":"僧兵","aliases":[],"readings":["そうへい"],"hint":"場所・人物・出来事をひと組にして考えよう。","explanation":"僧兵は武装した僧です。大寺院が朝廷に要求を通そうとするときなどに活動しました。","priority":1}}],"h24-m48":[{"revision":1,"kind":"initial","reason":"PR #18 baseline","question":{"id":"h24-m48","course":"memory","unit":"藤原氏と政治","type":"text","prompt":"1086年に院政を始めた人物は？","answer":"白河上皇","aliases":[],"readings":["しらかわじょうこう"],"hint":"人物・役職・年号のどれが聞かれているか見てみよう。","explanation":"1086年、白河天皇が位を譲って上皇となり、院政を始めました。平安時代がこの年に終わったわけではありません。","priority":2}}],"h24-m49":[{"revision":1,"kind":"initial","reason":"PR #18 baseline","question":{"id":"h24-m49","course":"memory","unit":"藤原氏と政治","type":"text","prompt":"上皇が政治を行うことを何という？","answer":"院政","aliases":[],"readings":["いんせい"],"hint":"人物・役職・年号のどれが聞かれているか見てみよう。","explanation":"天皇の位を退いた上皇が政治を行う仕組みを院政といいます。","priority":2}}],"h24-m50":[{"revision":1,"kind":"initial","reason":"PR #18 baseline","question":{"id":"h24-m50","course":"memory","unit":"藤原氏と政治","type":"text","prompt":"院政の開始により、それまでの力が弱まった政治の仕組みは？","answer":"摂関政治","aliases":[],"readings":["せっかんせいじ"],"hint":"人物・役職・年号のどれが聞かれているか見てみよう。","explanation":"院政で上皇に権力が集まり、藤原氏の摂関政治の力は弱まりました。摂政・関白が直ちになくなったわけではありません。","priority":1}}],"h24-p01":[{"revision":1,"kind":"initial","reason":"PR #18 baseline","question":{"id":"h24-p01","course":"pairs","unit":"藤原氏と政治","type":"choice","prompt":"道長と頼通の正しい組み合わせは？","options":["道長＝望月の歌、頼通＝平等院鳳凰堂","道長＝平等院鳳凰堂、頼通＝望月の歌","２つとも道長"],"answer":"道長＝望月の歌、頼通＝平等院鳳凰堂","hint":"父が道長、子が頼通だよ。","explanation":"望月の歌は道長。平等院鳳凰堂は1053年に頼通が建てました。","priority":1}}],"h24-p02":[{"revision":1,"kind":"initial","reason":"PR #18 baseline","question":{"id":"h24-p02","course":"pairs","unit":"武士の誕生","type":"choice","prompt":"939年の２つの反乱。正しい組み合わせは？","options":["関東＝藤原純友、瀬戸内海＝平将門","関東＝平将門、瀬戸内海＝藤原純友","関東も瀬戸内海も藤原純友"],"answer":"関東＝平将門、瀬戸内海＝藤原純友","hint":"新皇と名乗った人物が関東にいるよ。","explanation":"関東の平将門と瀬戸内海の藤原純友を対応させます。２つとも教材では939年の反乱として扱います。","priority":1}}],"h24-p03":[{"revision":1,"kind":"initial","reason":"PR #18 baseline","question":{"id":"h24-p03","course":"pairs","unit":"国風文化とくらし","type":"choice","prompt":"作品と作者の組み合わせが正しいものは？","options":["源氏物語＝清少納言、枕草子＝紫式部","源氏物語＝紫式部、枕草子＝清少納言","どちらも紀貫之"],"answer":"源氏物語＝紫式部、枕草子＝清少納言","hint":"紫式部は長編物語、清少納言は随筆を書いたよ。","explanation":"紫式部は源氏物語、清少納言は枕草子。紀貫之らは古今和歌集を編集しました。","priority":1}}],"h24-p04":[{"revision":1,"kind":"initial","reason":"PR #18 baseline","question":{"id":"h24-p04","course":"pairs","unit":"藤原氏と政治","type":"choice","prompt":"摂政と関白の説明で適切なのは？","options":["摂政＝幼い天皇などに代わる、関白＝成人した天皇を補佐","摂政＝上皇、関白＝武士の指導者","摂政＝成人した天皇だけを補佐、関白＝幼い天皇だけに代わる"],"answer":"摂政＝幼い天皇などに代わる、関白＝成人した天皇を補佐","hint":"天皇の年齢と役割に注目しよう。","explanation":"摂政は幼い天皇などに代わり政治を行い、関白は成人した天皇を補佐します。","priority":1}}],"h24-p05":[{"revision":1,"kind":"initial","reason":"PR #18 baseline","question":{"id":"h24-p05","course":"pairs","unit":"国風文化とくらし","type":"choice","prompt":"かな文字の作り方で正しいのは？","options":["ひらがな＝漢字の一部、カタカナ＝漢字をくずす","両方とも外国の文字と無関係","ひらがな＝漢字をくずす、カタカナ＝漢字の一部"],"answer":"ひらがな＝漢字をくずす、カタカナ＝漢字の一部","hint":"「安→あ」「阿→ア」を思い出そう。","explanation":"ひらがなは漢字をくずし、カタカナは漢字の一部を使って作られました。","priority":1}}],"h24-p06":[{"revision":1,"kind":"initial","reason":"PR #18 baseline","question":{"id":"h24-p06","course":"pairs","unit":"国風文化とくらし","type":"choice","prompt":"仕えた后と作家の組み合わせは？","options":["定子＝清少納言、彰子＝紫式部","定子＝紫式部、彰子＝清少納言","どちらも紫式部だけ"],"answer":"定子＝清少納言、彰子＝紫式部","hint":"道長の娘・彰子と源氏物語の作者がひと組だよ。","explanation":"清少納言は定子、紫式部は彰子に仕えました。","priority":1}}],"h24-p07":[{"revision":1,"kind":"initial","reason":"PR #18 baseline","question":{"id":"h24-p07","course":"pairs","unit":"武士の誕生","type":"choice","prompt":"源氏と平氏が力を伸ばした地域は？","options":["源氏＝西日本、平氏＝東日本","源氏＝東日本、平氏＝西日本","どちらも都の中だけ"],"answer":"源氏＝東日本、平氏＝西日本","hint":"源氏は東北の戦乱、平氏は瀬戸内海と結びつけよう。","explanation":"源氏は東日本、平氏は瀬戸内海を中心とする西日本に勢力を広げました。","priority":1}}],"h24-p08":[{"revision":1,"kind":"initial","reason":"PR #18 baseline","question":{"id":"h24-p08","course":"pairs","unit":"国風文化とくらし","type":"choice","prompt":"寝殿造と平等院鳳凰堂の説明は？","options":["寝殿造＝貴族の住宅の様式、鳳凰堂＝阿弥陀堂","寝殿造＝寺院、鳳凰堂＝国司の役所","どちらも武士の城"],"answer":"寝殿造＝貴族の住宅の様式、鳳凰堂＝阿弥陀堂","hint":"住まいと、仏さまをまつる建物を区別しよう。","explanation":"寝殿造は住宅の建築様式。平等院鳳凰堂は浄土への願いを表す阿弥陀堂です。","priority":1}}],"h24-p09":[{"revision":1,"kind":"initial","reason":"PR #18 baseline","question":{"id":"h24-p09","course":"pairs","unit":"武士の誕生","type":"choice","prompt":"国司と国府は、それぞれ何？","options":["国司＝場所、国府＝人","どちらも寺の名前","国司＝役人、国府＝地方政治の中心地"],"answer":"国司＝役人、国府＝地方政治の中心地","hint":"司は役目を表す字だよ。","explanation":"国司は派遣される役人、国府は政治を行う中心地です。","priority":1}}],"h24-p10":[{"revision":1,"kind":"initial","reason":"PR #18 baseline","question":{"id":"h24-p10","course":"pairs","unit":"国風文化とくらし","type":"choice","prompt":"古今和歌集と万葉集のうち、平安時代の最初の勅撰和歌集は？","options":["万葉集","古今和歌集","どちらも同じ本"],"answer":"古今和歌集","hint":"勅撰は、天皇の命令で編集することだよ。","explanation":"古今和歌集が最初の勅撰和歌集です。万葉集は奈良時代の歌集です。","priority":1}}],"h24-f01":[{"revision":1,"kind":"initial","reason":"PR #18 baseline","question":{"id":"h24-f01","course":"flow","unit":"藤原氏と政治","type":"structure","prompt":"次の出来事を、古い順に並べよう。","items":["平安京に都を移す","遣唐使の停止","939年の２つの反乱","道長が摂政になる","白河上皇が院政を始める"],"blanks":[],"answer":"平安京に都を移す → 遣唐使の停止 → 939年の２つの反乱 → 道長が摂政になる → 白河上皇が院政を始める","hint":"794→894→939→1016→1086の順だよ。","explanation":"反乱は道長の全盛期より前です。939年の反乱で摂関政治がすぐ衰えたとはいえません。","priority":1}}],"h24-f02":[{"revision":1,"kind":"initial","reason":"PR #18 baseline","question":{"id":"h24-f02","course":"flow","unit":"藤原氏と政治","type":"structure","prompt":"藤原氏が外戚として力を強める流れを並べよう。","items":["娘を天皇の后にする","娘の子が天皇になる","天皇の母方の親戚になる","摂政・関白として政治の実権を握る"],"blanks":[],"answer":"娘を天皇の后にする → 娘の子が天皇になる → 天皇の母方の親戚になる → 摂政・関白として政治の実権を握る","hint":"娘→孫→母方の親戚の順に考えよう。","explanation":"母方の親戚である外戚となることが、藤原氏の権力の基盤になりました。","priority":1}}],"h24-f03":[{"revision":1,"kind":"initial","reason":"PR #18 baseline","question":{"id":"h24-f03","course":"flow","unit":"武士の誕生","type":"structure","prompt":"武士が力を認められる流れを並べよう。","items":["各地で争いが起こる","武芸にすぐれた者が取りしまりにあたる","土地に住みついて豪族や農民と結びつく","武士団として勢力を広げる"],"blanks":[],"answer":"各地で争いが起こる → 武芸にすぐれた者が取りしまりにあたる → 土地に住みついて豪族や農民と結びつく → 武士団として勢力を広げる","hint":"争いをおさえる役目が、地域との結びつきにつながるよ。","explanation":"武芸にすぐれた下級貴族や地方の有力者らが結びつき、武士団が成長しました。","priority":1}}],"h24-f04":[{"revision":1,"kind":"initial","reason":"PR #18 baseline","question":{"id":"h24-f04","course":"flow","unit":"武士の誕生","type":"structure","prompt":"東北の戦乱と院政の「始まった年」を古い順に並べよう。","items":["前九年合戦の開始","後三年合戦の開始","白河上皇の院政開始"],"blanks":[],"answer":"前九年合戦の開始 → 後三年合戦の開始 → 白河上皇の院政開始","hint":"1051・1083・1086を使おう。","explanation":"後三年合戦は1087年まで続きます。院政開始は、その合戦が終わる前の1086年です。","priority":1}}],"h24-f05":[{"revision":1,"kind":"initial","reason":"PR #18 baseline","question":{"id":"h24-f05","course":"flow","unit":"藤原氏と政治","type":"structure","prompt":"院政が始まる流れを並べよう。","items":["白河天皇が子に位を譲る","白河上皇となる","上皇が政治を行う","上皇に権力が集まり摂関政治の力が弱まる"],"blanks":[],"answer":"白河天皇が子に位を譲る → 白河上皇となる → 上皇が政治を行う → 上皇に権力が集まり摂関政治の力が弱まる","hint":"位を譲っても、政治から離れなかったよ。","explanation":"上皇が政治を行う院政が始まり、藤原氏が外戚として力を振るう仕組みに変化が起きました。","priority":1}}],"h24-f06":[{"revision":1,"kind":"initial","reason":"PR #18 baseline","question":{"id":"h24-f06","course":"flow","unit":"藤原氏と政治","type":"choice","prompt":"遣唐使停止の理由として適切でないものは？","options":["航海の危険が大きかった","唐の力が衰えていた","唐と新羅の間で戦争が起きた"],"answer":"唐と新羅の間で戦争が起きた","hint":"894年当時の背景に合うか考えよう。","explanation":"唐と新羅の戦争を、この時の停止理由として選ぶのは誤りです。年代と背景を結びつけましょう。","priority":1}}],"h24-f07":[{"revision":1,"kind":"initial","reason":"PR #18 baseline","question":{"id":"h24-f07","course":"flow","unit":"武士の誕生","type":"choice","prompt":"939年の反乱後の変化として適切なのは？","options":["武士の力が認められ、貴族が武士を雇うようになった","この年に藤原氏の政治が完全に終わった","武士が全員いなくなった"],"answer":"武士の力が認められ、貴族が武士を雇うようになった","hint":"反乱をしずめたのは誰の力だったかな？","explanation":"朝廷が武士の力を借りて反乱をしずめたことで、武士の重要性が高まりました。","priority":1}}],"h24-f08":[{"revision":1,"kind":"initial","reason":"PR #18 baseline","question":{"id":"h24-f08","course":"flow","unit":"国風文化とくらし","type":"choice","prompt":"国風文化の発達について適切なのは？","options":["894年の１日で中国文化がすべて消えた","学んだ中国文化を日本の暮らしに合わせて発展させた","かな文字は中国文化と全く関係がない"],"answer":"学んだ中国文化を日本の暮らしに合わせて発展させた","hint":"漢字をもとにかな文字ができたことも手がかりだよ。","explanation":"中国文化の影響を受けながら、日本に合った文化へと発展しました。停止だけを唯一の原因にはしません。","priority":1}}],"h24-f09":[{"revision":1,"kind":"initial","reason":"PR #18 baseline","question":{"id":"h24-f09","course":"flow","unit":"武士の誕生","type":"choice","prompt":"武士の成長を説明するものとして適切でないのは？","options":["貴族の警護にあたった","地方の豪族や農民と結びついた","国司の不正だけで、全員が自動的に武士になった"],"answer":"国司の不正だけで、全員が自動的に武士になった","hint":"武芸や、土地の人々との結びつきが大切だよ。","explanation":"国司の不正は地方政治の問題ですが、それだけが武士誕生の仕組みではありません。武芸や地域の結びつきが関係します。","priority":1}}],"h24-f10":[{"revision":1,"kind":"initial","reason":"PR #18 baseline","question":{"id":"h24-f10","course":"flow","unit":"藤原氏と政治","type":"choice","prompt":"1086年に始まった院政について正しいのは？","options":["この年に平安時代が終わった","白河上皇が位を譲った後も政治を行った","摂政と関白という役職がすぐ消滅した"],"answer":"白河上皇が位を譲った後も政治を行った","hint":"天皇の位と、政治を行う人が分かれたよ。","explanation":"1086年は院政の開始年です。平安時代はその後も続き、摂政・関白の役職も残りました。","priority":1}}],"h24-r01":[{"revision":1,"kind":"initial","reason":"PR #18 baseline","question":{"id":"h24-r01","course":"reason","unit":"藤原氏と政治","type":"structure","prompt":"摂政と関白を、天皇の成長と役割に合わせて説明しよう。","items":["幼い天皇などに代わって政治を行う","成長して成人した天皇を補佐する"],"blanks":[{"label":"幼い天皇などに代わる役職","answer":"摂政","options":["摂政","関白","国司"]},{"label":"成人した天皇を補佐する役職","answer":"関白","options":["関白","摂政","上皇"]}],"answer":"幼い天皇などに代わって政治を行う → 成長して成人した天皇を補佐する / 摂政・関白","hint":"天皇が幼い場合と成人した場合を分けよう。","explanation":"摂政は幼い天皇などに代わって政治を行う役職、関白は成人した天皇を補佐する役職です。実際の任命は歴史上さまざまで、自動的に交代する制度という意味ではありません。","priority":1}}],"h24-r02":[{"revision":1,"kind":"initial","reason":"PR #18 baseline","question":{"id":"h24-r02","course":"reason","unit":"藤原氏と政治","type":"structure","prompt":"藤原氏が大きな力を持った理由を組み立てよう。","items":["娘を天皇の后にする","生まれた子を天皇の位につける","母方の親戚として政治に関わる"],"blanks":[{"label":"母方の親戚を表す言葉","answer":"外戚","options":["外戚","国司","僧兵"]},{"label":"収入のもとになった私有地","answer":"荘園","options":["荘園","国府","大宰府"]}],"answer":"娘を天皇の后にする → 生まれた子を天皇の位につける → 母方の親戚として政治に関わる / 外戚・荘園","hint":"家族のつながりと、収入のもとの２つだよ。","explanation":"娘を天皇の后にし、その子が天皇になることで外戚となり、摂政・関白として力を強めました。荘園からの収入や、政敵を退けたことも支えになりました。","priority":1}}],"h24-r03":[{"revision":1,"kind":"initial","reason":"PR #18 baseline","question":{"id":"h24-r03","course":"reason","unit":"国風文化とくらし","type":"structure","prompt":"国風文化が発達した背景を説明しよう。","items":["中国の文化を受け入れる","日本の風土や暮らしに合う形に発展させる","日本語による文学などが豊かになる"],"blanks":[{"label":"日本語を書くために発達した文字","answer":"かな文字","options":["かな文字","アルファベット","数字"]},{"label":"894年に派遣が停止されたもの","answer":"遣唐使","options":["遣唐使","国司","僧兵"]}],"answer":"中国の文化を受け入れる → 日本の風土や暮らしに合う形に発展させる → 日本語による文学などが豊かになる / かな文字・遣唐使","hint":"受け入れた文化を日本に合わせていく流れだよ。","explanation":"中国文化を日本の風土や暮らしに合わせて発展させ、かな文字による文学などが栄えました。遣唐使停止はこの動きを後押ししましたが、交流がすべてなくなったわけではありません。","priority":1}}],"h24-r04":[{"revision":1,"kind":"initial","reason":"PR #18 baseline","question":{"id":"h24-r04","course":"reason","unit":"武士の誕生","type":"structure","prompt":"武士が生まれ、力を広げた背景を説明しよう。","items":["武芸にすぐれた者が争いの取りしまりにあたる","派遣先に住みつき地域の有力者と結びつく","武装集団として勢力を広げる"],"blanks":[{"label":"結びついた地域の人々","answer":"豪族や農民","options":["豪族や農民","外国の使節だけ","都の后だけ"]},{"label":"成長した武装集団","answer":"武士団","options":["武士団","遣唐使","国風文化"]}],"answer":"武芸にすぐれた者が争いの取りしまりにあたる → 派遣先に住みつき地域の有力者と結びつく → 武装集団として勢力を広げる / 豪族や農民・武士団","hint":"武芸と地域のつながりがキーワードだよ。","explanation":"地方に住みついた武芸にすぐれた貴族などが、豪族や農民らと結びつき、武士団として成長しました。自分たちの土地を守る動きも関係します。","priority":1}}],"h24-r05":[{"revision":1,"kind":"initial","reason":"PR #18 baseline","question":{"id":"h24-r05","course":"reason","unit":"藤原氏と政治","type":"structure","prompt":"院政で摂関政治の力が弱まった理由を説明しよう。","items":["天皇が位を譲って上皇となる","上皇が政治の実権を握る","外戚である藤原氏の影響力が相対的に弱まる"],"blanks":[{"label":"上皇が行う政治","answer":"院政","options":["院政","摂関政治","国風文化"]},{"label":"1086年に始めた人物","answer":"白河上皇","options":["白河上皇","藤原純友","菅原道真"]}],"answer":"天皇が位を譲って上皇となる → 上皇が政治の実権を握る → 外戚である藤原氏の影響力が相対的に弱まる / 院政・白河上皇","hint":"天皇の母方の親戚だけが政治を動かす形ではなくなったよ。","explanation":"天皇の父などである上皇に権力が集まり、外戚の藤原氏が政治を主導する力は弱まりました。摂関政治や役職が一度に消えた、とは考えません。","priority":1}}]};
MODES.adaptive='弱点に合わせた追加練習';MODES.daily='今日の5問';
function grade(q,response,variant){
 if(q.type==='choice')return response===q.answer;
 if(q.type==='text'){const allowed=[q.answer,...q.aliases,...(variant==='kanji'?[]:q.readings)];return allowed.some(a=>normalize(a)===normalize(response));}
 return JSON.stringify(response.steps)===JSON.stringify(q.items.map((_,i)=>i))&&JSON.stringify(response.fills)===JSON.stringify(q.blanks.map(b=>b.answer));
}
function check(ok,msg){if(!ok)throw Error(msg);}
function validDate(s){return typeof s==='string'&&/^\d{4}-\d\d-\d\dT\d\d:\d\d:\d\d\.\d{3}Z$/.test(s)&&Number.isFinite(Date.parse(s))&&new Date(s).toISOString()===s;}
function validateEvent(e){
 check(e&&typeof e==='object','回答の形式が不正です。');const q=historicalQuestion(e);
 check(q&&e.version===VERSION,'対応していない問題ID・問題版です。元ファイルを保管してください。');
 for(const k of ['id','sessionId'])check(typeof e[k]==='string'&&/^[a-zA-Z0-9_-]{8,100}$/.test(e[k]),'回答ID・セッションIDが不正です。');
 check(e.unit===q.unit&&e.course===q.course&&e.question===q.prompt&&e.expected===q.answer&&e.explanation===q.explanation,'問題情報がこの版と一致しません。');
 check(['normal','kanji'].includes(e.variant)&&(q.type==='text'||e.variant==='normal')&&Object.hasOwn(MODES,e.mode),'確認方法・モードが不正です。');
 check(validDate(e.at)&&Number.isInteger(e.offset)&&Math.abs(e.offset)<=840&&e.day===day(e.at,e.offset),'回答日時が不正です。');
 check(typeof e.hint==='boolean'&&typeof e.correct==='boolean'&&typeof e.reflection==='string'&&e.reflection.length<=2000,'ヒント・正誤・記述の形式が不正です。');
 let response=e.response;
 if(q.type==='text')check(typeof response==='string'&&response.trim().length>0&&response.length<=200,'入力回答が不正です。');
 else if(q.type==='choice')check(q.options.includes(response),'選択肢が不正です。');
 else{check(response&&Array.isArray(response.steps)&&response.steps.length===q.items.length&&new Set(response.steps).size===q.items.length&&response.steps.every(i=>Number.isInteger(i)&&i>=0&&i<q.items.length)&&Array.isArray(response.fills)&&response.fills.length===q.blanks.length&&response.fills.every((s,i)=>q.blanks[i].options.includes(s)),'並べ替え・穴埋めの形式が不正です。');response={steps:[...response.steps],fills:[...response.fills]};}
 check(e.correct===grade(q,response,e.variant),'採点結果と記録の正誤が一致しません。');
 check(q.course==='reason'||e.reflection==='','この問題に自由記述はありません。');
 return {...(Object.hasOwn(e,'questionVersion')?{questionVersion:e.questionVersion}:{}),id:e.id,sessionId:e.sessionId,questionId:q.id,version:VERSION,unit:q.unit,course:q.course,question:q.prompt,response,expected:q.answer,explanation:q.explanation,correct:e.correct,variant:e.variant,mode:e.mode,hint:e.hint,reflection:e.reflection,at:e.at,offset:e.offset,day:e.day};
}
function validate(v){
 check(v&&v.schemaVersion===1&&v.datasetVersion===VERSION&&Array.isArray(v.events),'この単元のJSONではありません。以前の記録や理科のJSONは元のアプリで保管してください。');
 const seen=new Map();for(const raw of v.events){const e=validateEvent(raw);check(!seen.has(e.id)||JSON.stringify(seen.get(e.id))===JSON.stringify(e),'同じ回答IDに異なる内容があります。全体の読み込みを中止しました。');seen.set(e.id,e);}
 return {...empty(),events:order([...seen.values()])};
}
function historicalQuestion(e){
 const science=typeof byId!=='undefined';
 const extra=!science&&e.questionId.endsWith('-review-v1');
 const id=extra?e.questionId.slice(0,-10):e.questionId;
 const records=QUESTION_REVISIONS[id]||[];
 const matches=[];
 for(const r of records){
  if(Object.hasOwn(e,'questionVersion')&&e.questionVersion!==r.revision)continue;
  const q=extra?{...r.question,id:e.questionId,originId:id,prompt:'復習：'+r.question.prompt}:r.question;
  const prompt=science?q.prompt:typeof promptOf==='function'?promptOf(q,e.variant):q.prompt;
  const expected=science?q.answer:typeof expectedOf==='function'?expectedOf(q,e.variant):q.answer;
  if(e.unit===q.unit&&(science?e.type===q.type:e.course===q.course)&&e.question===prompt&&e.expected===expected&&e.explanation===q.explanation)matches.push(q);
 }
 // Versionless histories can match multiple spelling revisions. Select the one
 // whose historical grade matches, without recalculating or rewriting the event.
 return matches.find(q=>e.correct===grade(q,e.response,e.variant));
}
return raw=>raw===null?empty():validate(JSON.parse(raw));
